_PATTERN=re.compile('|'.join(re.escape(k) for k in sorted(TRANSLATIONS,key=len,reverse=True)))
def text(value):return _PATTERN.sub(lambda match:TRANSLATIONS[match.group()],value)
def localize(value):
 if isinstance(value,str):return text(value)
 if isinstance(value,list):return [localize(item) for item in value]
 if isinstance(value,dict):return {key:localize(item) for key,item in value.items()}
 return value
